// Mi Ozorio — valida token, roteia por kind e monta a mensagem (voz da Mi).
// Telefone vem em E.164 (+55...); a Evolution quer só dígitos.
const TOKEN = $env.MI_WEBHOOK_TOKEN || '';
const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const body = j.body || j;        // o webhook coloca o corpo em .body
  const headers = j.headers || {};

  // Token compartilhado com o app (N8N_WEBHOOK_TOKEN). Se vazio, não checa.
  if (TOKEN && headers['x-webhook-token'] !== TOKEN) {
    throw new Error('Token de webhook inválido');
  }

  const number = String(body.telefone || '').replace(/\D/g, '');
  if (!number) throw new Error('telefone ausente no payload');
  const nome = body.nome || '';
  let text;

  if (body.kind === 'club_points') {
    // <!-- APROVAR COM A MI --> (Clube por pontos)
    const motivo = body.motivo ? ` (${body.motivo})` : '';
    text = `Oi, ${nome}! 💛\n\nVocê ganhou ${body.pontos} pontos no Clube Mi Ozorio${motivo}! Acompanhe seu saldo e troque por mimos quando quiser. 💛`;
  } else if (body.kind === 'booking_confirmation') {
    // <!-- APROVAR COM A MI -->
    const inicio = body.inicio
      ? new Date(body.inicio).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', dateStyle: 'short', timeStyle: 'short' })
      : '';
    text = `Oi, ${nome}! 💛\n\nSeu horário de ${body.servico} está confirmado para ${inicio}.\n\nQualquer coisa, é só me chamar por aqui. Até logo! 💛`;
  } else {
    throw new Error('kind desconhecido: ' + body.kind);
  }

  out.push({ json: { number, text, kind: body.kind } });
}

return out;
